<?php if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/applications-center/')));exit;}get_header();$u=wp_get_current_user();$client=legacyx_find_client_by_wp_user(get_current_user_id());$apps=$client?legacyx_get_client_applications($client->ID):array();$counts=$client?legacyx_application_counts($client->ID):array('active'=>0,'approved'=>0,'closed'=>0,'total'=>0);?><main class="legacyx-credit-center"><div class="legacyx-credit-shell"><a class="legacyx-credit-back" href="<?php echo esc_url(home_url('/client-portal/'));?>">← Client Command Center</a><header class="legacyx-credit-head"><div><span class="kicker">LEGACY X FIRM OS · APPLICATIONS</span><h1>Applications Center</h1><p>Track funding, grants, onboarding and other authorized applications connected to your Universal Client Profile.</p></div><div class="legacyx-credit-identity"><span>Client</span><strong><?php echo esc_html($u->display_name?:$u->user_login);?></strong><?php if($client):?><small><?php echo esc_html(get_post_meta($client->ID,'_legacyx_client_id',true));?></small><?php endif;?></div></header><?php if(!$client):?><div class="legacyx-portal-notice"><strong>Applications connection pending.</strong> Your Universal Client Profile must be linked before application data can be displayed.</div><?php else:?><section class="legacyx-credit-summary"><div><span>Total Applications</span><strong><?php echo esc_html($counts['total']);?></strong></div><div><span>Active</span><strong><?php echo esc_html($counts['active']);?></strong></div><div><span>Approved / Funded</span><strong><?php echo esc_html($counts['approved']);?></strong></div><div><span>Closed</span><strong><?php echo esc_html($counts['closed']);?></strong></div></section><section class="legacyx-credit-action"><span>Application Control</span><p>Your Legacy X Firm team can update statuses, requested amounts, deadlines, required documents and outcomes from the private administration console.</p></section><section class="legacyx-credit-track"><div class="legacyx-track-title"><span>APPLICATION PIPELINE</span><h2>My Applications</h2><p>Only records tied to your own Universal Client Profile are shown here. Select an application to open its private detail view.</p></div><div class="legacyx-step-list"><?php if(!$apps):?><article class="legacyx-credit-step"><span class="legacyx-step-num">—</span><div><h3>No applications recorded yet</h3><p>Your funding, grant, onboarding or other application records will appear here when added by your Legacy X Firm team.</p></div></article><?php else:foreach($apps as $i=>$app):$type=get_post_meta($app->ID,'_legacyx_type',true);$status=get_post_meta($app->ID,'_legacyx_status',true);$amount=get_post_meta($app->ID,'_legacyx_requested_amount',true);$provider=get_post_meta($app->ID,'_legacyx_provider',true);$detail=home_url('/applications-center/application/'.$app->ID.'/');?><a href="<?php echo esc_url($detail);?>" style="display:block;color:inherit;text-decoration:none" aria-label="Open <?php echo esc_attr(get_the_title($app));?>"><article class="legacyx-credit-step"><span class="legacyx-step-num"><?php echo sprintf('%02d',$i+1);?></span><div><h3><?php echo esc_html(get_the_title($app));?></h3><p><strong>Type:</strong> <?php echo esc_html($type?:'Not specified');?> · <strong>Status:</strong> <?php echo esc_html($status?:'Pending');?><?php if($amount):?> · <strong>Amount:</strong> <?php echo esc_html($amount);?><?php endif;?><?php if($provider):?><br><strong>Provider / Program:</strong> <?php echo esc_html($provider);?><?php endif;?></p></div><b aria-hidden="true">→</b></article></a><?php endforeach;endif;?></div></section><?php endif;?></div></main><?php get_footer();?>